-- FinCERT content (spec 053), generated by specs/053-fincert-page/seed/build-seed.mjs from the legacy CMS page
-- `fincert` (page 133, test API). Do not edit by hand: change the generator and ship a new migration.
-- 4 directions (az + en), 1 membership (FIRST: az from Figma, en a draft to check), contacts, portal, RFC-2350.
--
-- RFC-2350: the legacy file is a link to uploads.cbar.az and is not in the media library of the test environment
-- (research R10). A media file with the legacy file name is used when one exists; otherwise the legacy link is kept
-- in rfc_url, so the section does not disappear on deploy day. An editor who uploads the document replaces it.
-- The FIRST logo is uploaded from the panel. Page texts are not touched: page 133 stays the fallback (FR-016).
--
-- Runs once: only while a non-deleted page with the az slug `fincert` exists and the three FinCERT tables are empty
-- (deleted rows included), so a second run, or a run after an editor deleted a row, creates nothing.
-- "FinCERT (Kopya)" (`fincert-copy`, page 479) leaves the left menus (spec 041/048).
DO $fincertseed$
DECLARE
    d_id integer;
    m_id integer;
    rfc_az bigint;
    rfc_en bigint;
BEGIN
    IF NOT EXISTS (
        SELECT FROM pages p JOIN page_translations t ON t.page_id = p.id
        WHERE t.locale = 'az' AND t.slug = 'fincert' AND p.deleted_at IS NULL
    ) THEN
        RAISE NOTICE 'spec 053: page fincert not found, FinCERT seed skipped';
        RETURN;
    END IF;
    IF EXISTS (SELECT FROM fincert_settings) OR EXISTS (SELECT FROM fincert_directions)
       OR EXISTS (SELECT FROM fincert_memberships) THEN
        RAISE NOTICE 'spec 053: FinCERT tables are not empty, FinCERT seed skipped';
        RETURN;
    END IF;

    SELECT id INTO rfc_az FROM media_assets
    WHERE original_name = $fincert$f7322827bd3688a2be3136204.pdf$fincert$ AND deleted_at IS NULL ORDER BY id LIMIT 1;
    SELECT id INTO rfc_en FROM media_assets
    WHERE original_name = $fincert$02c3d655e376515419c623ce2.pdf$fincert$ AND deleted_at IS NULL ORDER BY id LIMIT 1;

    INSERT INTO fincert_settings (id, email, phone, portal_url)
    VALUES (1, $fincert$fincert@cbar.az$fincert$, $fincert$(+994 12) 437 00 97$fincert$, $fincert$https://portal.e-cbar.az/$fincert$);
    INSERT INTO fincert_setting_translations
        (settings_id, locale, mission, portal_title, portal_description, rfc_media_id, rfc_url) VALUES
        (1, 'az', $fincert$Azərbaycan Respublikasının Mərkəzi Bankı (Mərkəzi Bank) tərəfindən yaradılmış Maliyyə sektorunda sahəvi Kompüter İnsidentlərinə qarşı Mübarizə Mərkəzinin (FinCERT) missiyası maliyyə bazarının kibertəhlükəsizlik səviyyəsini və dayanıqlılığını gücləndirməkdir.$fincert$, $fincert$Vahid Elektron Hesabatlılıq Portalı$fincert$, $fincert$Yüksək kateqoriyalı insidentlər üzrə hesabatlar nəzarət subyektləri tərəfindən Mərkəzi Banka bu portal vasitəsilə göndərilir.$fincert$, rfc_az, CASE WHEN rfc_az IS NULL THEN $fincert$https://uploads.cbar.az/assets/f7322827bd3688a2be3136204.pdf$fincert$ END),
        (1, 'en', $fincert$The mission of the Financial Computer Emergency Response Center (FinCERT), established by the Central Bank of the Republic of Azerbaijan (Central Bank), is to strengthen the level of cybersecurity and resilience of the financial market.$fincert$, $fincert$Unified Electronic Reporting Portal$fincert$, $fincert$The Central Bank's "Unified Electronic Reporting Portal" is used by supervised entities to submit reports on high-category incidents to the Central Bank.$fincert$, rfc_en, CASE WHEN rfc_en IS NULL THEN $fincert$https://uploads.cbar.az/assets/02c3d655e376515419c623ce2.pdf$fincert$ END);

    -- 1. İnsidentlər barədə məlumatların əldə olunması və paylaşılması
    INSERT INTO fincert_directions (sort_order, status) VALUES (1, 'published') RETURNING id INTO d_id;
    INSERT INTO fincert_direction_translations (direction_id, locale, title, body) VALUES
        (d_id, 'az', $fincert$İnsidentlər barədə məlumatların əldə olunması və paylaşılması$fincert$, $fincert$<p>FinCERT maliyyə bazar iştirakçılarına təsir edən kibertəhlükəsizlik insidentləri barədə məlumatların mərkəzləşdirilmiş formada toplanmasını və vaxtında paylaşılmasını təmin edir.</p>
<p>FinCERT bu istiqamətdə:</p>
<ul><li>qanunvericilik çərçivəsində CERT-lər ilə sıx kommunikasiya və əməkdaşlıq həyata keçirir;</li>
<li>maliyyə bazarlarında kibertəhlükəsizlik səviyyəsinin artırılmasını təmin edən effektiv kommunikasiya mühitini formalaşdırır;</li>
<li>beynəlxalq maliyyə CERT-ləri ilə əməkdaşlıq edərək qlobal ən yaxşı təcrübələri tətbiq edir.</li>
</ul>$fincert$),
        (d_id, 'en', $fincert$Obtaining and Sharing of Information on Incidents$fincert$, $fincert$<p>FinCERT ensures the centralized collection and timely sharing of information regarding cybersecurity incidents affecting financial market participants. FinCERT:</p>
<ul><li>closely communicates and cooperates with other CERTs within the legislative framework.</li>
<li>forms an effective communication environment that ensures the enhancement of cybersecurity in financial markets.</li>
<li>implements global best practices by cooperating with international financial CERTs.</li>
</ul>$fincert$);
    -- 2. İnsidentlərin təhlili və ilkin cavab tədbirlərinin təmin olunması
    INSERT INTO fincert_directions (sort_order, status) VALUES (2, 'published') RETURNING id INTO d_id;
    INSERT INTO fincert_direction_translations (direction_id, locale, title, body) VALUES
        (d_id, 'az', $fincert$İnsidentlərin təhlili və ilkin cavab tədbirlərinin təmin olunması$fincert$, $fincert$<p>FinCERT daxil olan məlumatları analiz edərək insidentlərin əsas səbəblərini müəyyənləşdirir, onların maliyyə sektoruna təsirini qiymətləndirir və müvafiq tərəflərin uyğun tədbirlər görməsini təmin etmək üçün operativ məlumat mübadiləsini və istiqamətləndirici tövsiyələrin təqdim olunmasını təmin edir.</p>$fincert$),
        (d_id, 'en', $fincert$Incident Analysis and Provision of Initial Response Measures$fincert$, $fincert$<p>By analyzing incoming information, FinCERT identifies the root causes of incidents, assesses their impact on the financial sector, and ensures operational information exchange and the provision of guiding recommendations to ensure that relevant parties take appropriate measures.</p>$fincert$);
    -- 3. İnsidentlər üzrə fəaliyyətin koordinasiyası və maliyyə ekosistemində dayanıqlılığın gücləndirilməsi
    INSERT INTO fincert_directions (sort_order, status) VALUES (3, 'published') RETURNING id INTO d_id;
    INSERT INTO fincert_direction_translations (direction_id, locale, title, body) VALUES
        (d_id, 'az', $fincert$İnsidentlər üzrə fəaliyyətin koordinasiyası və maliyyə ekosistemində dayanıqlılığın gücləndirilməsi$fincert$, $fincert$<p>FinCERT maliyyə bazarı iştirakçıları, CERT-lər və digər maraqlı tərəflər arasında koordinasiyanı təmin etməklə insidentlərə cavab proseslərini vahid formada təşkil edir. Bu koordinasiya nəticəsində sektor üzrə daha sürətli və effektiv reaksiya göstərilir, maliyyə sisteminin dayanıqlılığı artırılır.</p>
<p>FinCERT eyni zamanda:</p>
<ul><li>maliyyə bazarında kibertəhlükəsizlik üzrə bilik və bacarıqların artırılmasına şərait yaradır;</li>
<li>maarifləndirmə təşəbbüsləri vasitəsilə kibergigiyena səviyyəsini yüksəldir;</li>
<li>rəqəmsal kanallar üzərindən CERT-lərlə sıx əməkdaşlıqda kibertəhlükəsizlik məlumatlarının yayılmasını təmin edir.</li>
</ul>$fincert$),
        (d_id, 'en', $fincert$Coordination of Incident Activities and Strengthening Resilience in the Financial Ecosystem$fincert$, $fincert$<p>FinCERT organizes unified incident response processes by ensuring coordination between financial market participants, CERTs, and other stakeholders. This coordinated approach enables faster and more effective responses across the sector and strengthens the resilience of the financial system. FinCERT also:</p>
<ul><li>creates conditions for increasing knowledge and skills in cybersecurity in the financial market.</li>
<li>raises the level of cyber hygiene through awareness initiatives.</li>
<li>ensures the dissemination of cybersecurity information through digital channels in close cooperation with CERTs.</li>
</ul>$fincert$);
    -- 4. Təhdidlərin proaktiv aşkarlanması və iştirakçıların əvvəlcədən xəbərdar edilməsi
    INSERT INTO fincert_directions (sort_order, status) VALUES (4, 'published') RETURNING id INTO d_id;
    INSERT INTO fincert_direction_translations (direction_id, locale, title, body) VALUES
        (d_id, 'az', $fincert$Təhdidlərin proaktiv aşkarlanması və iştirakçıların əvvəlcədən xəbərdar edilməsi$fincert$, $fincert$<p>FinCERT-in fəaliyyət istiqamətlərindən biri də maliyyə sektorunu hədəfləyən kibertəhdidlərin proaktiv şəkildə aşkarlanması və onların mümkün nəticələrinin qarşısının alınmasıdır. Bu çərçivədə FinCERT müxtəlif məlumatların toplanması və təhlili mexanizmlərindən istifadə etməklə yeni və yaranmaqda olan təhdidlərin identifikasiyasını həyata keçirir, onların maliyyə institutlarına potensial təsirlərini qiymətləndirir və müvafiq qabaqlayıcı tədbirlərin görülməsi üçün iştirakçıları vaxtında məlumatlandırır.</p>
<p>Bu fəaliyyət nəticəsində maliyyə sektoru üzrə risklərin əvvəlcədən müəyyən olunması təmin edilir, bazar iştirakçılarının insidentlərə hazırlıq səviyyəsi artırılır və ümumi kiberdayanıqlılıq gücləndirilir.</p>$fincert$),
        (d_id, 'en', $fincert$Proactive Threat Detection and Early Warning of Participants$fincert$, $fincert$<p>One of FinCERT's areas of activity is the proactive detection of cybersecurity threats targeting the financial sector and the prevention of their possible consequences. In this framework, FinCERT identifies new and emerging threats by using various data collection and analysis mechanisms, assesses their potential impact on financial institutions, and timely informs participants to take appropriate preventive measures.</p>
<p>With these efforts, the financial sector identifies risks proactively, enhances the preparedness among market participants and strengthens overall cyber resilience</p>$fincert$);

    INSERT INTO fincert_memberships (url, sort_order, status) VALUES ($fincert$https://www.first.org/$fincert$, 1, 'published') RETURNING id INTO m_id;
    INSERT INTO fincert_membership_translations (membership_id, locale, name, description, badge) VALUES
        (m_id, 'az', $fincert$Forum for Incident Response and Security Teams$fincert$, $fincert$İnsidentlərlə Mübarizə və Təhlükəsizlik Mərkəzlərinin Beynəlxalq Forumu$fincert$, $fincert$2026-cı ildən tam hüquqlu üzv$fincert$),
        (m_id, 'en', $fincert$Forum of Incident Response and Security Teams$fincert$, $fincert$International forum of incident response and security teams$fincert$, $fincert$Full member since 2026$fincert$);

    -- In shared environments page_details may belong to another role (see 0028).
    IF has_table_privilege('page_details', 'INSERT') AND has_table_privilege('page_details', 'UPDATE') THEN
        INSERT INTO page_details (page_id, show_in_side_nav)
        SELECT t.page_id, false FROM page_translations t
        WHERE t.locale = 'az' AND t.slug = 'fincert-copy'
        ON CONFLICT (page_id) DO UPDATE SET show_in_side_nav = false;
    ELSE
        RAISE WARNING 'spec 053: no INSERT/UPDATE on page_details, fincert-copy stays in the menus';
    END IF;

    RAISE NOTICE 'spec 053: fincert seeded (directions 4, memberships 1, rfc az=% en=%)',
        CASE WHEN rfc_az IS NULL THEN 'url' ELSE 'media' END, CASE WHEN rfc_en IS NULL THEN 'url' ELSE 'media' END;
END
$fincertseed$;
